function pickWeek(n){if(state.week!==Number(n)){state.word=null;state.glossaryQuery='';}state.week=Number(n);state.verse=null;state.context=true;storage.set('week',state.week);}
function studySelector(){const groups=groupSessions(curriculum.sessions,state.rhythm);const index=groups.findIndex(g=>g.some(s=>s.number===state.week));return `<div class="study-selector"><div class="selector-fields"><label for="rhythm">Frecuencia de reunión<select id="rhythm"><option value="weekly" ${state.rhythm==='weekly'?'selected':''}>Cada semana</option><option value="fortnightly" ${state.rhythm==='fortnightly'?'selected':''}>Cada dos semanas</option></select></label><label for="week">${state.rhythm==='weekly'?'Semana de estudio':'Encuentro quincenal'}<select id="week">${groups.map((g,i)=>`<option value="${g[0].number}" ${i===index?'selected':''}>${g.map(s=>weekLabel(s.date)).join(' + ')} · ${g.length===1?g[0].passage:'Semanas '+g[0].number+' & '+g[1].number}</option>`).join('')}</select></label></div><div class="week-arrows"><button class="icon-button" data-week="${groups[index-1]?.[0].number||1}" ${index===0?'disabled':''} aria-label="Estudio anterior">←</button><button class="icon-button" data-week="${groups[index+1]?.[0].number||12}" ${index===groups.length-1?'disabled':''} aria-label="Estudio siguiente">→</button></div></div>${state.rhythm==='fortnightly'?'<p class="rhythm-note">Usen las mismas tres preguntas para ambos pasajes. Lleven la pregunta puente de la segunda semana al próximo encuentro.</p>':''}`;}
function pastoralIntro(){return `<section class="pastoral-intro" aria-labelledby="pastoral-welcome"><div class="eyebrow">CRECEMOS JUNTOS EN LA PALABRA</div><h3 id="pastoral-welcome">${esc(pastoralIntroduction.title)}</h3><p class="pastoral-welcome">${esc(pastoralIntroduction.welcome)}</p><p class="pastoral-credit">Lean, observen, interpreten y apliquen cada pasaje. Al final de un módulo, La historia hasta aquí reúne las escenas alrededor de la pregunta que nos ha guiado.</p></section>`;}
function intro(){return heading('01','El Rey ha venido','Una historia, doce semanas y espacio para crecer juntos.','ACTO I')+`<div class="welcome-copy"><p>${esc(curriculum.welcome)}</p><div class="series-facts"><span><strong>12</strong> estudios semanales</span><span><strong>3</strong> módulos y un interludio</span><span><strong>1</strong> historia que lo une todo</span></div></div>${pastoralIntro()}<div class="section-subhead"><h3>Tu recorrido por el Acto I</h3><span>Octubre – diciembre de 2026</span></div><div class="module-grid">${curriculum.modules.slice(0,3).map(m=>`<article class="module-card"><div class="module-body"><div class="eyebrow">MÓDULO ${m.id} · ${esc(moduleWeeks(m.id))}</div><h3>${esc(m.name)}</h3><p class="big-question">${esc(artAvailable(curriculum.sessions.find(s=>s.module===m.id))?m.question:openingLabel(curriculum.sessions.find(s=>s.module===m.id)))}</p><p>${esc(m.description)}</p></div></article>`).join('')}</div><div class="interlude"><span class="step">12</span><div><div class="eyebrow">SEMANA DEL 28 DE DICIEMBRE · INTERLUDIO</div><h3>Treinta años después…</h3><p>${esc(curriculum.modules[3].description)}</p></div></div><section class="method-section"><h3>Cómo estudiamos juntos</h3><p>Comiencen con la Biblia, escúchense con atención y dejen que cada escena guíe la conversación.</p><div class="method-grid">${weeklyStudy.method.map((m,i)=>`<article><small>0${i+1}</small><h4>${m.title}</h4><p>${esc(m.question)}</p></article>`).join('')}</div></section><div class="two-rhythms"><h3>Un plan de estudio. Dos maneras de reunirse.</h3><p>Si el grupo se reúne cada semana, sigan un pasaje y sus preguntas. Si se reúnen cada dos semanas, junten los dos estudios más recientes y usen las mismas tres preguntas para conversar. Todos siguen la misma historia, y la segunda pregunta puente acompaña al grupo quincenal hasta su próximo encuentro.</p><p class="annotation">Comienza en Leer el texto y elige tu semana de estudio.</p></div>${future()}`;}
function future(){return `<div class="future-act">${icon('lock')}<div><span class="eyebrow">CONTINUARÁ EN 2027</span><h3>Acto II · El Rey comienza su ministerio</h3><p>Nuestro recorrido continuará hacia Jerusalén, la cruz, la resurrección y el testimonio de la iglesia. Estos estudios posteriores aún no están abiertos; sus fechas y contenidos se anunciarán más adelante.</p></div><span class="tag">BLOQUEADO</span></div>`;}
function highlighted(text,week=state.week){if(!state.word||!state.showWord||week!==state.week)return esc(text);const forms=[...state.word.forms].sort((a,b)=>b.length-a.length).map(f=>f.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));const re=new RegExp(`(?<![\\p{L}])(${forms.join('|')})(?![\\p{L}])`,'giu');let output='',last=0;for(const match of text.matchAll(re)){output+=esc(text.slice(last,match.index))+`<mark>${esc(match[0])}</mark>`;last=match.index+match[0].length;}return output+esc(text.slice(last));}
function chapter(s){return bible.chapters[s.book+'.'+s.chapter];}
function readVerses(s){return state.context?Object.entries(chapter(s).verses).map(([verse,text])=>({verse:Number(verse),text,key:`${s.book}.${s.chapter}.${verse}`})):s.verses;}
function reading(){
 return heading('02','Leer el texto','Lee el capítulo completo, con el pasaje de esta semana resaltado. Deja que el texto guíe la conversación.','RV1909')+studySelector()+currentGroup().map(s=>{
  const m=curriculum.modules.find(m=>m.id===s.module),c=chapter(s);
  const verses=Object.entries(c.verses).map(([n,text])=>{const v=Number(n),focus=v>=s.start&&v<=s.end,key=`${s.book}.${s.chapter}.${v}`;let copy=highlighted(text,s.number);
   if(s.partialEnd&&v===s.end){const excerpt=s.verses.at(-1).text;copy=`<span class="study-verse-part">${highlighted(excerpt,s.number)}</span><span class="context-remainder">${highlighted(text.slice(excerpt.length),s.number)}</span>`;}
   return `${v===s.start?`<div class="passage-start" id="study-start-${s.number}" tabindex="-1"><span class="eyebrow">PASAJE DE ESTA SEMANA · ${esc(s.passage)}</span></div>`:''}<p id="verse-${s.number}-${v}" tabindex="-1" class="verse ${focus?'focus-verse':'context-verse'} ${s.partialEnd&&v===s.end?'partial-verse':''}"><span class="verse-num" aria-label="Versículo ${v}">${v}</span>${copy}</p>`;
  }).join('');
  return `<article class="reading-session"><header class="reading-session-head"><span class="eyebrow">${weekLabel(s.date)} · ${moduleLabel(s.module).toUpperCase()}</span><h3>${esc(sessionTitle(s))}</h3></header><div class="paper chapter-paper"><div class="reader-toolbar"><div><strong>${esc(c.book)} ${s.chapter} · Capítulo completo</strong><p class="annotation">El borde color vino señala ${esc(s.passage)}. Los versículos cercanos siguen visibles para dar contexto.</p><button class="text-link" data-study-jump="${s.number}">Ir al pasaje de estudio ↓</button></div><div class="type-tools"><button data-size="-1" aria-label="Reducir tamaño del texto bíblico">A−</button><button data-size="1" aria-label="Aumentar tamaño del texto bíblico">A+</button></div></div>${s.number===state.week?`<div class="word-highlight-control"><label><input type="checkbox" data-show-word ${state.showWord?'checked':''} ${state.word?'':'disabled'}><span>Mostrar la palabra seleccionada en Herramientas de estudio bíblico${state.word?` · <strong>${esc(state.word.word)}</strong>`:''}</span></label>${state.word?'':'<p class="annotation">Selecciona una palabra clave en Herramientas de estudio bíblico para resaltarla aquí.</p>'}</div>`:''}<div class="reading-text">${verses}</div><div class="scripture-credit">Reina-Valera 1909 · Dominio público. Se conserva el texto de esta edición. ${s.partialEnd?'El estudio resalta solo la primera frase de Miqueas 5:5; el resto del versículo permanece visible.':''}</div></div>${sceneConnections(s)}<section class="reading-discussion"><h3>Exploremos juntos esta escena</h3>${questions(s)}</section><div class="reading-next">${s.number!==currentGroup().at(-1).number?'':s.number<12?`<button class="secondary-button" data-read="${s.number+1}">Continuar a ${weekLabel(curriculum.sessions[s.number].date)} →</button>`:'<a class="secondary-button" href="#story">Volver a La historia hasta aquí →</a>'}</div></article>`;
 }).join('');
}
function verseLabel(key){const [b,c,v]=key.split('.');return `${bible.chapters[b+'.'+c]?.book||({'2Sam':'2 Samuel',Isa:'Isaías',Mic:'Miqueas'}[b]||b)} ${c}:${v}`;}
const bookNames={"Gen": "Génesis", "Exod": "Éxodo", "Lev": "Levítico", "Num": "Números", "Deut": "Deuteronomio", "Josh": "Josué", "Judg": "Jueces", "Ruth": "Rut", "1Sam": "1 Samuel", "2Sam": "2 Samuel", "1Kgs": "1 Reyes", "2Kgs": "2 Reyes", "1Chr": "1 Crónicas", "2Chr": "2 Crónicas", "Ezra": "Esdras", "Neh": "Nehemías", "Esth": "Ester", "Job": "Job", "Ps": "Salmos", "Prov": "Proverbios", "Eccl": "Eclesiastés", "Song": "Cantares", "Isa": "Isaías", "Jer": "Jeremías", "Lam": "Lamentaciones", "Ezek": "Ezequiel", "Dan": "Daniel", "Hos": "Oseas", "Joel": "Joel", "Amos": "Amós", "Obad": "Abdías", "Jonah": "Jonás", "Mic": "Miqueas", "Nah": "Nahúm", "Hab": "Habacuc", "Zeph": "Sofonías", "Hag": "Hageo", "Zech": "Zacarías", "Mal": "Malaquías", "Matt": "Mateo", "Mark": "Marcos", "Luke": "Lucas", "John": "Juan", "Acts": "Hechos", "Rom": "Romanos", "1Cor": "1 Corintios", "2Cor": "2 Corintios", "Gal": "Gálatas", "Eph": "Efesios", "Phil": "Filipenses", "Col": "Colosenses", "1Thess": "1 Tesalonicenses", "2Thess": "2 Tesalonicenses", "1Tim": "1 Timoteo", "2Tim": "2 Timoteo", "Titus": "Tito", "Phlm": "Filemón", "Heb": "Hebreos", "Jas": "Santiago", "1Pet": "1 Pedro", "2Pet": "2 Pedro", "1John": "1 Juan", "2John": "2 Juan", "3John": "3 Juan", "Jude": "Judas", "Rev": "Apocalipsis"};
function refLabel(key){if(passages?.[key])return passages[key].label;const [a,b]=key.split('-');const [book,c,v]=a.split('.');const end=b?.split('.');return `${bookNames[book]||book} ${c}:${v}${b?'–'+(end[1]===c?end[2]:end[1]+':'+end[2]):''}`;}
function scopeSessions(){return [session()];}
function analysisVerses(){return scopeSessions().flatMap(s=>s.verses.map(v=>({...v,week:s.number,label:chapter(s).book+' '+s.chapter+':'+v.verse+(v.part||'')})));}

function toolsWeekSelector(){return `<div class="study-selector tools-week-selector"><label for="week">Semana de estudio<select id="week">${curriculum.sessions.map(s=>`<option value="${s.number}" ${s.number===state.week?'selected':''}>${weekLabel(s.date)} · ${esc(s.passage)}</option>`).join('')}</select></label><div class="week-arrows"><button class="icon-button" data-week="${state.week-1}" ${state.week===1?'disabled':''} aria-label="Semana de estudio anterior">←</button><button class="icon-button" data-week="${state.week+1}" ${state.week===12?'disabled':''} aria-label="Semana de estudio siguiente">→</button></div></div><p class="tools-passage-note">Las tres herramientas siguientes corresponden a <strong>${esc(session().passage)}</strong>.</p>`;}
function words(){const verses=analysisVerses(),list=analyze(verses,'keywords');let word=state.word?list.find(w=>w.word===state.word.word):list[0];state.word=word||null;const max=list[0]?.count||1;return '<h3 class="tool-heading">Palabras repetidas · Palabras clave</h3>'+`<p class="word-reading-notice"><strong>La palabra clave que selecciones aquí aparecerá resaltada en Leer el texto.</strong> Usa «Mostrar la palabra seleccionada en Herramientas de estudio bíblico» en la lectura para activar o desactivar el resaltado.${!state.showWord?' <strong>El resaltado está desactivado.</strong>':''}</p><p class="info-note">Las cápsulas más grandes indican más repeticiones en ${esc(session().passage)}. Se cuentan juntas las formas españolas indicadas, incluida la ortografía de 1909; no son recuentos del hebreo ni del griego.</p><div class="paper word-cloud">${list.slice(0,50).map(w=>{const ratio=w.count/max,tier=ratio>=.8?5:ratio>=.5?4:ratio>=.3?3:ratio>=.2?2:1;return `<button class="word-cloud-pill frequency-${tier} ${word?.word===w.word?'active':''}" data-word="${esc(w.word)}" aria-pressed="${word?.word===w.word}" aria-label="${esc(w.word)}, ${w.count} apariciones"><span>${esc(w.word)}</span><b>${w.count}</b></button>`}).join('')||'<p>No se repiten palabras clave en este pasaje.</p>'}</div>${word?`<section class="word-insight" id="word-insight"><span class="eyebrow">EN ESTE PASAJE · ${esc(session().passage)}</span><h3>${esc(word.word)}</h3><div class="word-meaning">${paragraphs(word.definition)}</div><p class="annotation">Una ayuda que puedes considerar junto al pasaje y las observaciones de tu grupo.</p></section>`:''}`;}
const moduleLabel=id=>id===4?'Interludio':'Módulo '+id;
const moduleState=id=>{const source=reflections?.modules.find(m=>m.id===id),full=approvedStories?.modules.find(m=>m.id===id);return {...source,...(full?.reading?full:{}),id,releaseAt:journey.storyDates[id],released:Date.now()>=Date.parse(journey.storyDates[id]),available:storyAvailable(id)};};
const currentModule=()=>[...curriculum.sessions].reverse().find(s=>Date.now()>=Date.parse(lessonMeta(s)?.releaseAt))?.module||1;
const glossaryModule=g=>curriculum.sessions[g.week-1].module;
async function openModuleReading(id,sectionId){
 if(!storyAvailable(id))return;
 try{await ensureStories()}catch{showToast('No se pudo cargar la lectura. Intenta de nuevo.');return}
 const module=moduleState(id),reading=module?.reading,topic=selectStoryTopic(reading,sectionId);
 if(!module?.available||!topic)return;
 const blocks=topic.blocks.map(b=>b.kind==='quote'?`<blockquote class="module-scripture"><cite>${esc(b.reference)}</cite>${paragraphs(b.text)}</blockquote>`:b.kind==='heading'?`<h4>${esc(b.text)}</h4>`:paragraphs(b.text)).join('');
 openDialog(`ACTO I / HISTORIA / ${moduleLabel(id).toUpperCase()}`,topic.title,
 `<div class="module-reading-meta">${topic.wordCount.toLocaleString('es-ES')} palabras · Unos ${topic.minutes} minutos</div><div class="module-reading-content"><section class="module-reading-section"><img src="./assets/${topic.image}" alt="${esc(topic.alt)}" width="1774" height="887">${blocks}</section></div><p class="pastoral-credit">${esc(reading.credit)}</p><p class="reading-return-note">Cierra esta lectura para volver al mismo lugar en ${esc(moduleLabel(id))}.</p>`);
}
function openConcept(index){const card=concepts[index];if(card)openModuleReading(card.module,'theme-'+index);}
function filterGlossary(){
 const q=state.glossaryQuery.trim().toLowerCase(),entries=glossaryForWeek(glossary,session());
 const found=entries.filter(g=>(g.word+' '+g.forms.join(' ')+' '+g.definition).toLowerCase().includes(q));
 $('#glossary-list').innerHTML=found.map(glossaryItem).join('')||'<p class="annotation">No hay términos coincidentes en este pasaje. Prueba otra palabra.</p>';
 $('#glossary-status').textContent=`${found.length} de ${entries.length} términos · ${session().passage}`;
}

function jumpToGlossary(word){closeDialog();state.tool='glossary';state.glossaryQuery=word;go('tools',false);$('#glossary-search').focus({preventScroll:true});$('#glossary-heading').scrollIntoView({block:'start',behavior:motionEnabled()?'smooth':'auto'});const match=[...$('#glossary-list').querySelectorAll('details')].find(el=>el.querySelector('summary span').textContent===word);if(match)match.open=true;}
function moduleReflections(m){
 return `<section class="reflection-module minimal-story-module ${storyAvailable(m.id)?'is-open':'is-locked'}" aria-labelledby="reflection-module-${m.id}"><h3 id="reflection-module-${m.id}">${esc(m.name)}</h3><div class="module-art">${moduleArt(m)}</div></section>`;
}
function conceptsView(){return heading('04','La historia hasta aquí','Detente al final de cada módulo para ver cómo sus escenas pertenecen a una sola historia.','3 MÓDULOS + INTERLUDIO')+curriculum.modules.map(moduleReflections).join('');}

function glossaryView(){return `<section class="pastoral-glossary" aria-labelledby="glossary-heading"><h3 id="glossary-heading">Glosario de esta semana</h3><p>Palabras e ideas vinculadas a ${esc(session().passage)}. Algunos títulos nombran un tema y no una palabra exacta del texto. Las conexiones invitan a comparar y dejan espacio para las observaciones del grupo.</p><div class="glossary-tools weekly-glossary-search"><label for="glossary-search">Busca un término de este pasaje<input id="glossary-search" type="search" placeholder="Buscar en el glosario de esta semana…" value="${esc(state.glossaryQuery)}"></label></div><p id="glossary-status" class="glossary-count" role="status"></p><div id="glossary-list" class="glossary-list"></div></section>`;}

function glossaryItem(g){return `<details class="glossary-item"><summary><span>${esc(g.word)}</span><b aria-hidden="true">+</b></summary><div class="definition">${paragraphs(g.definition)}<p class="glossary-context">Pasaje de esta semana · ${esc(g.reference)}</p></div></details>`;}
function methodCards(){return `<div class="question-set">${weeklyStudy.method.map((m,i)=>`<section class="study-question"><span class="question-label">0${i+1} · ${esc(m.title)}</span><p>${esc(m.question)}</p></section>`).join('')}</div>`;}
function questions(s){if(!artAvailable(s))return methodCards()+`<section class="narrative-bridge"><span class="eyebrow">UNA PREGUNTA PARA SEGUIR PENSANDO</span><p>${esc(openingLabel(s))}. Vuelve entonces para ver la pregunta de esta semana.</p></section>`;return methodCards()+`<section class="narrative-bridge"><span class="eyebrow">UNA PREGUNTA PARA SEGUIR PENSANDO</span><p>${esc(weeklyStudy.sessions[s.number-1].bridgeQuestion)}</p><p class="bridge-invitation">${esc(weeklyStudy.discussionNote)}</p></section>`;}
function lessonMeta(s){return catalog?.lessons?.find(l=>l.id===s.id)}
function statusCard(s){const l=lessonMeta(s);if(l?.status==='available')return `<div class="commentary-ready"><span>El comentario pastoral está disponible</span><button class="primary-button" data-lesson="${s.id}">Leer comentario ↗</button></div>`;return `<div class="awaiting-commentary">${icon('lock')}<div><strong>${l?.status==='scheduled'?'Comentario programado':'En espera del contenido de los pastores'}</strong><p>Para la ${weekLabel(s.date)}. ${l?.status==='scheduled'?'Disponible durante esta semana de estudio.':'La lectura y la guía para conversar están listas en Leer el texto. El comentario aparecerá cuando los pastores lo entreguen y comience la semana correspondiente.'}</p></div></div>`;}
function studiesView(){const selected=session();return progressSummary()+`<div class="pastoral-progress-control"><p class="eyebrow">${weekLabel(selected.date)} · ${esc(selected.passage)}</p>${completionControl(selected)}</div><section class="all-studies pastoral-studies"><div class="section-subhead"><h3>Las doce semanas</h3><label for="module-filter" class="sr-only">Filtrar semanas por módulo</label><select id="module-filter"><option value="all">Todos los módulos</option>${curriculum.modules.map(m=>`<option value="${m.id}" ${state.module===String(m.id)?'selected':''}>${m.id===4?'Interludio':'Módulo '+m.id}</option>`).join('')}</select></div><div class="pastoral-week-list">${curriculum.sessions.filter(s=>state.module==='all'||s.module===Number(state.module)).map(s=>{
 const open=artAvailable(s),available=lessonMeta(s)?.status==='available',current=s.number===selected.number;
 return `<article class="pastoral-week-row ${current?'current':''}" aria-label="${weekLabel(s.date)}"><button class="pastoral-week-select" data-pastoral-week="${s.number}" aria-pressed="${current}" aria-label="Seleccionar ${weekLabel(s.date)}: ${esc(sessionTitle(s))}">${sessionArt(s,true)}<span class="pastoral-week-copy"><span class="schedule-date">${weekLabel(s.date)}</span><strong>${esc(sessionTitle(s))}</strong><small>${esc(s.passage)}</small></span></button><div class="pastoral-week-action">${available?`<button class="primary-button" data-lesson="${s.id}" aria-label="Leer comentarios de ${weekLabel(s.date)}">Leer comentarios ↗</button>`:`<span class="pastoral-week-status">${icon('lock')}${open?'Comentario próximamente':esc(openingLabel(s))}</span>`}</div></article>`;
 }).join('')}</div></section>${future()}`;}
function resourcesView(){return heading('06','Recursos externos','Elige la herramienta que te ayude con la pregunta que estás explorando.','11 RECURSOS')+`<section class="resource-intro"><h3>Comienza con la Escritura. Después explora.</h3><p>Estos enlaces reúnen las herramientas de las dos páginas de la guía de recursos bíblicos D-Groups. Úsalos después de leer el pasaje por ti mismo y lleva las preguntas pendientes a tu grupo. Algunos sitios externos ofrecen contenido en inglés; su idioma depende de cada proveedor.</p></section>${['Contexto histórico','Estudiar el pasaje','Lugares y palabras'].map((category,i)=>`<section class="resource-section"><h3>${category}</h3><div class="resource-grid">${resources.filter(r=>r[2]===category).map(([name,url,,copy])=>`<a class="resource-card" href="${url}" target="_blank" rel="noopener noreferrer"><h4 class="resource-brand">${esc(name.split(' · ')[0])}${name.includes(' · ')?`<span class="resource-service">${esc(name.split(' · ')[1])}</span>`:''}</h4><p>${copy}</p><small>${new URL(url).hostname}</small><span class="text-link">Abrir recurso ↗</span></a>`).join('')}</div></section>`).join('')}<section class="method-section"><h3>Una guía sencilla para el tiempo juntos</h3><p>Adaptado del método D-Groups: observar, interpretar, aplicar, animarse mutuamente y orar.</p>${[...weeklyStudy.method.map(m=>[m.title,m.question]),...methodGuide.slice(3)].map(([title,copy],i)=>`<details class="method-detail"><summary><span>0${i+1} · ${title}</span><b>+</b></summary><p>${copy}</p></details>`).join('')}</section>`;}
function render(){if(!curriculum)return;disposeSceneMotion();$('.series-hero').hidden=state.view!=='introduction';updateLocation();$('#view').innerHTML=`<div class="study-panel">${sectionBanner()}${({introduction:intro,reading,tools:toolsView,story:conceptsView,studies:studiesView,resources:resourcesView}[state.view])()}</div>`;wire();wireFrames($('#view'));disposeSceneMotion=wireSceneMotion(document);lastGateSignature=gateSignature();scheduleWeekOpening();}
function openDialog(kicker,title,body){modalVersion++;$('#detail').classList.remove('commentary-reader');$('.commentary-font-controls')?.remove();$('#dialog-kicker').textContent=kicker;$('#dialog-body').innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${body}`;if(!$('#detail').open){document.documentElement.classList.add('dialog-open');$('#detail').showModal();}$('#detail').scrollTop=0;return modalVersion;}
function closeDialog(){modalVersion++;$('#detail').close();document.documentElement.classList.remove('dialog-open');}
$('#detail').addEventListener('close',()=>document.documentElement.classList.remove('dialog-open'));
$('#close-dialog').onclick=closeDialog;$('#detail').addEventListener('cancel',()=>modalVersion++);
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});

async function loadReferences(){if(passages)return passages;if(!referencePromise)referencePromise=fetchJSON('./references.json').then(data=>passages=data).catch(e=>{referencePromise=null;throw e});return referencePromise;}
async function openReference(ref){const version=openDialog('REINA-VALERA 1909',refLabel(ref),'<p role="status">Abriendo el pasaje relacionado…</p>');try{await loadReferences();if(version!==modalVersion||!$('#detail').open)return;const p=passages[ref];if(!p)throw Error('Missing reference');$('#dialog-body').innerHTML=`<h2 id="dialog-title">${esc(p.label)}</h2>${p.verses.map(v=>`<p class="scripture-quote"><sup>${v.chapter}:${v.verse}</sup>${esc(v.text)}</p>`).join('')}<p>Lee el capítulo completo antes de decidir cómo se relacionan los pasajes.</p><a class="text-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Leer el capítulo en eBible.org ↗</a>`;wireModal();}catch{if(version===modalVersion)$('#dialog-body').innerHTML=`<h2 id="dialog-title">No se pudo cargar este pasaje</h2><p>Revisa tu conexión e intenta de nuevo.</p><button class="primary-button" data-ref="${ref}">Intentar de nuevo</button>`;wireModal();}}
function guide(n){const s=curriculum.sessions[n-1];openDialog(`${weekLabel(s.date)}`,sessionTitle(s),`<p>${esc(s.passage)}</p>${questions(s)}<button class="primary-button" data-study="${s.number}">Abrir el estudio</button>`);wireModal();}
async function openLesson(id){const l=catalog.lessons.find(l=>l.id===id);if(l?.status!=='available')return;const version=openDialog('COMENTARIO PASTORAL',l.title,'<p role="status">Abriendo el comentario…</p>');try{const data=await fetchJSON(`${$('meta[name="lesson-base"]').content}/${encodeURIComponent(id)}/lesson.json`,{cache:'no-store'});if(version!==modalVersion||!$('#detail').open)return;commentaryTextControls();$('#dialog-body').innerHTML=`<h2 id="dialog-title">${esc(data.title)}</h2><section class="commentary-opening" aria-labelledby="commentary-opening-title"><h3 id="commentary-opening-title">Antes de comenzar</h3>${commentaryParagraphs(commentaryPreface)}<p class="commentary-authority"><strong>${esc(commentaryAuthority)}</strong></p></section>${commentaryParagraphs(commentaryIntroduction(data.introduction))}${data.points.map((p,i)=>`<section><h3>${i+1}. ${esc(p.title)}</h3><div class="point-reference">${esc(p.reference)}</div>${p.image?`<img src="${$('meta[name="lesson-base"]').content}/${id}/${encodeURIComponent(p.image)}" alt="${esc(p.alt)}" loading="lazy">`:''}${commentaryParagraphs(p.text)}</section>`).join('')}${data.finalWord?`<h3>Para terminar</h3>${commentaryParagraphs(data.finalWord)}`:''}<p class="annotation">Enseñanza preparada por los pastores de EIC Paris.</p>`;}catch{if(version===modalVersion)$('#dialog-body').innerHTML='<h2 id="dialog-title">Comentario no disponible</h2><p>Intenta de nuevo más tarde. Es posible que la enseñanza aún no esté disponible para esta semana.</p>';}}
function wireModal(){ $('#dialog-body').querySelectorAll('[data-glossary-jump]').forEach(b=>b.onclick=()=>jumpToGlossary(b.dataset.glossaryJump)); $('#dialog-body').querySelectorAll('[data-ref]').forEach(b=>b.onclick=()=>openReference(b.dataset.ref));$('#dialog-body').querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>{closeDialog();pickWeek(b.dataset.study);go('studies')});$('#dialog-body').querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{closeDialog();pickWeek(b.dataset.read);go('reading')});}
function wire(){
 document.querySelectorAll('[data-module-jump]').forEach(b=>b.onclick=()=>$('#reflection-module-'+b.dataset.moduleJump).scrollIntoView({block:'start',behavior:motionEnabled()?'smooth':'auto'}));
 $('[data-glossary-all]')?.addEventListener('click',()=>{state.glossaryQuery='';render();$('#glossary-search').focus({preventScroll:true});$('#glossary-heading').scrollIntoView({block:'start'})});
 $('#week')?.addEventListener('change',e=>{pickWeek(e.target.value);render();$('#week').focus({preventScroll:true})});
 $('#rhythm')?.addEventListener('change',e=>{state.rhythm=e.target.value;storage.set('rhythm',state.rhythm);state.word=null;state.verse=null;render();$('#rhythm').focus({preventScroll:true})});
 document.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.week);render()});
 document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.read);go('reading')});
 document.querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.study);go('studies')});
 document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{const m=Number(b.dataset.module);pickWeek(curriculum.sessions.find(s=>s.module===m).number);state.module=String(m);go('studies')});
 $('[data-open-classes]')?.addEventListener('click',()=>go('studies'));
 $('#context')?.addEventListener('change',e=>{state.context=e.target.checked;render();$('#context').focus()});
 document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{state.size=Math.min(25,Math.max(16,state.size+Number(b.dataset.size)));storage.set('size',state.size);document.documentElement.style.setProperty('--reading-size',state.size+'px')});

 document.querySelectorAll('[data-ref]').forEach(b=>b.onclick=()=>openReference(b.dataset.ref));
 document.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>guide(Number(b.dataset.guide)));
 document.querySelectorAll('[data-show-word]').forEach(b=>b.onchange=()=>{state.showWord=b.checked;storage.set('show-word',String(state.showWord));const index=[...document.querySelectorAll('[data-show-word]')].indexOf(b);render();document.querySelectorAll('[data-show-word]')[index]?.focus({preventScroll:true});});
 document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{state.word=analyze(analysisVerses(),'keywords').find(w=>w.word===b.dataset.word);render();$(`[data-word="${state.word.word}"]`)?.focus({preventScroll:true});$('#word-insight').scrollIntoView({block:'nearest',behavior:motionEnabled()?'smooth':'auto'})});
 document.querySelectorAll('[data-hit]').forEach(b=>b.onclick=()=>{const [week,verse]=b.dataset.hit.split(':').map(Number);const word=state.word;pickWeek(week);state.word=word;state.rhythm='weekly';storage.set('rhythm','weekly');state.verse=`${session().book}.${session().chapter}.${verse}`;go('reading',false);requestAnimationFrame(()=>{$(`#verse-${week}-${verse}`)?.scrollIntoView({block:'center'});$(`#verse-${week}-${verse}`)?.focus({preventScroll:true})})});
 document.querySelectorAll('[data-concept]').forEach(b=>b.onclick=()=>openConcept(Number(b.dataset.concept)));
 wireJourney();
 if($('#glossary-list'))filterGlossary();
 $('#glossary-search')?.addEventListener('input',e=>{state.glossaryQuery=e.target.value;filterGlossary()});
 document.querySelectorAll('[data-pastoral-week]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.pastoralWeek);render();document.querySelector(`[data-pastoral-week="${state.week}"]`)?.focus({preventScroll:true});});
 document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{const id=b.dataset.lesson;const s=curriculum.sessions.find(s=>s.id===id);if(state.view==='studies'&&s){pickWeek(s.number);render();document.querySelector(`[data-lesson="${id}"]`)?.focus({preventScroll:true});}openLesson(id);});
 $('#module-filter')?.addEventListener('change',e=>{state.module=e.target.value;render();$('#module-filter').focus({preventScroll:true})});
}
$('#sources').onclick=()=>openDialog('D-GROUPS · ACERCA DE','Crecemos juntos en la Palabra.',`<section class="about-credits"><h3>Equipo pastoral</h3><p><strong>EIC Rueil-Malmaison:</strong><br>Jeff Walters — Pastor principal<br>Christian Nartatez — Pastor asociado</p><p><strong>EIC Rive Gauche:</strong><br>John Hugh — Pastor principal</p><h3>Desarrollado por</h3><p>The Graphic Department at EIC Paris</p></section>
<h3>Texto bíblico</h3><p>La <a href="https://ebible.org/spaRV1909/" target="_blank" rel="noopener noreferrer">Reina-Valera 1909</a> es de dominio público. Los doce pasajes del Acto I, sus siete capítulos completos y los pasajes relacionados se reproducen del archivo oficial de eBible, sin traducirlos mediante inteligencia artificial. Se conserva la ortografía de esta edición, que puede resultar antigua. En ella, «salud» puede significar salvación. Miqueas 5:5a muestra solo la primera frase; el versículo completo se conserva en el capítulo.</p>
<h3>Pasajes que amplían la escena</h3><p>Cada estudio incluye dos pasajes seleccionados para explorar la pregunta del módulo y el puente narrativo final. Las notas breves orientan la lectura; el grupo puede seguir otras observaciones y aplicaciones que surjan de los textos.</p>
<h3>Concordancia bíblica TSK</h3><p>El <a href="https://www.openbible.info/labs/cross-references/" target="_blank" rel="noopener noreferrer">conjunto de referencias de OpenBible.info</a> se basa principalmente en Treasury of Scripture Knowledge e incluye conexiones adicionales. La fuente contiene 3.333 relaciones para los siete capítulos, con 2.733 pasajes distintos. La concordancia muestra seis conexiones seleccionadas por semana. Las explicaciones son ayudas editoriales, no citas de TSK. Se utiliza bajo licencia <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>, con una selección y adaptación al español. Una referencia cruzada es un punto de partida para comparar; no demuestra por sí sola que dos pasajes signifiquen lo mismo.</p>
<h3>Plan de estudio y recursos</h3><p>Los doce pasajes, el recorrido narrativo y las introducciones de los módulos proceden del plan de EIC Paris «De Belén a las naciones, Acto I», de octubre a diciembre de 2026. Las tres preguntas breves se adaptaron de las secciones de observación, interpretación y aplicación de la guía D-Groups de 1 Pedro. Sus fechas y lecturas de 2025 no corresponden a esta serie. Cada semana conserva una pregunta puente. Los recursos externos proceden de las dos páginas de la guía de herramientas bíblicas; sus idiomas dependen de cada sitio.</p>
<h3>Vocabulario semanal</h3><p>Las notas de palabras clave siguen el pasaje semanal elegido. El glosario selecciona conceptos relacionados, incluidos títulos que no aparecen literalmente en ese pasaje. El contexto histórico se explica mediante los relatos bíblicos, como 2 Reyes 15:29, 1 Crónicas 24, Éxodo 30:7–8 y Levítico 12. Estas ayudas distinguen las repeticiones en español del estudio de palabras hebreas o griegas y ofrecen comparaciones con Lucas–Hechos para conversar.</p><h3>Notas y enseñanza pastoral</h3><p>Las notas, los textos de enseñanza y los comentarios pastorales son desarrollados por el pastor asociado Christian Nartatez en EIC Rueil-Malmaison, bajo la supervisión de los pastores principales de EIC Paris. Esta edición ofrece una traducción española del material aprobado. Las citas bíblicas usan la Reina-Valera 1909; los puntos y su orden se conservan.</p>
<h3>Ilustraciones y diseño</h3><p>Las ilustraciones de formas geométricas Low Poly y sombreado Cel Shading fueron generadas con inteligencia artificial como representaciones simbólicas, no como reconstrucciones arqueológicas. El diseño sigue las apps de estudio D-Groups y EIC Paris.</p>
<h3>Tus preferencias</h3><p>Los estudios completados, la frecuencia de reunión, la semana elegida, el resaltado de palabras, el tema, las animaciones y los tamaños del texto bíblico y del comentario se guardan en este navegador. Las animaciones comienzan activadas; puedes apagarlas con el botón superior. El progreso no se sincroniza entre dispositivos ni con la app inglesa. Borrar los datos del sitio lo elimina. Si el almacenamiento no está disponible, la marca dura solo durante la visita. La edición de revisión guarda su progreso por separado.</p><p>El título, la ilustración, la pregunta narrativa y el botón para completar cada semana se abren el lunes a las 06:00, hora de París. Completar un estudio no permite adelantar semanas futuras. Las reflexiones se abren al completar el módulo o terminar su período. Los comentarios siguen su propio calendario de publicación; el comentario de la semana 1 se abrió anticipadamente el 11 de octubre. Esta app no recoge nombres ni notas compartidas. El Acto II y las enseñanzas posteriores aún no están incluidos.</p>
`);
async function fetchJSON(url,options){const r=await fetch(url,options);if(!r.ok)throw Error(`${r.status}`);return r.json();}
async function loadReflections(){
 const url=$('meta[name="reflection-catalog"]').content;
 const next=await fetchJSON(url,{cache:'no-store'});
 reflections=next;
}
async function refreshReleases(){
 if(!curriculum)return;
 const before=JSON.stringify(reflections),beforeCatalog=JSON.stringify(catalog);
 try{await loadReflections();catalog=await fetchJSON($('meta[name="lesson-catalog"]').content,{cache:'no-store'});if(curriculum.modules.some(m=>storyAvailable(m.id)))await ensureStories();if(!$('#detail').open&&(before!==JSON.stringify(reflections)||beforeCatalog!==JSON.stringify(catalog)||lastGateSignature!==gateSignature()))render()}catch{/* Keep the last verified view; a reload retries the request. */}
}
window.addEventListener('focus',refreshReleases);
setInterval(()=>{if(!document.hidden)refreshReleases()},60000);
async function start(){try{[curriculum,bible,catalog,journey,weeklyStudy]=await Promise.all([fetchJSON('./curriculum.json?v=20261023-week2'),fetchJSON('./data.json'),fetchJSON($('meta[name="lesson-catalog"]').content,{cache:'no-store'}),fetchJSON('./journey.json?v=20261023-week2'),fetchJSON('./weekly-study.json',{cache:'no-store'})]);await loadReflections();completed=readProgress();if(curriculum.modules.some(m=>storyAvailable(m.id)))await ensureStories();go(location.hash.slice(1)||'introduction',false);}catch{$('#view').innerHTML='<div class="error"><h2>No se pudo abrir el estudio</h2><p>Revisa tu conexión y vuelve a cargar la página.</p><button id="retry" class="primary-button">Intentar de nuevo</button></div>';$('#retry').onclick=start}}
start();


function progressKey(){return reflections?.review?'review-progress-v1':'progress-v1';}
function readProgress(){try{const key='lucas-hechos-es-'+progressKey(),raw=localStorage.getItem(key),saved=parseProgress(raw),valid=eligibleProgress(saved,catalog.lessons);if(valid.length!==saved.length)localStorage.setItem(key,JSON.stringify({version:1,completed:valid}));progressSaved=true;return valid;}catch{progressSaved=false;return [];}}
function storyAvailable(id){return storyOpen(id,curriculum.sessions,completed,journey.storyDates[id],Date.now(),false,journey.storyUnlock);}
function artAvailable(s){return weekOpen(lessonMeta(s)?.releaseAt);}
function openingLabel(s){return 'Se abre en la '+weekLabel(s.date).toLocaleLowerCase('es');}
function sessionTitle(s){return artAvailable(s)?(journey.sessions[s.number-1].commentaryTitle||s.title):openingLabel(s);}
function scheduleWeekOpening(){clearTimeout(releaseTimer);const next=catalog.lessons.map(l=>Date.parse(l.releaseAt)).filter(t=>t>Date.now()).sort((a,b)=>a-b)[0];if(next)releaseTimer=setTimeout(()=>{if(!$('#detail').open)render();refreshReleases();},Math.min(next-Date.now()+20,2147483647));}
function gateSignature(){return JSON.stringify([curriculum.sessions.map(artAvailable),curriculum.modules.map(m=>storyAvailable(m.id))]);}
function showToast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function lockedCover(compact=false){return `<span class="series-cover ${compact?'compact-cover':''}"><img src="./assets/series-mosaic.webp" alt="${compact?'':esc(journey.seriesCover.alt)}" width="1774" height="887" loading="lazy"><span class="series-wordmark"><span class="series-lock">${icon('lock')}</span><strong>De Belén<br>a las naciones</strong><small>SERIE DE ESTUDIOS BÍBLICOS D-GROUP</small></span></span>`;}
function sessionArt(s,compact=false){const item=journey.sessions[s.number-1],open=artAvailable(s),done=open&&completed.includes(s.number);return `<span class="session-art journey-frame ${done?'is-complete':''} ${compact?'session-thumb':''}" data-session-art="${s.number}">${open?`<img src="./assets/${item.image}?v=20261012-diversity" alt="${compact?'':esc(item.alt)}" width="1774" height="887" loading="lazy">`:lockedCover(compact)}${done?'<span class="completed-badge">✓ Completado</span>':!open&&!compact?`<span class="art-unlock">${esc(openingLabel(s))} · lunes a las 06:00, hora de París.</span>`:''}</span>`;}
function moduleArt(m){const c=concepts.find(c=>c.module===m.id);return storyAvailable(m.id)?`<img src="./assets/${c.image}" alt="${esc(c.alt)}" width="1774" height="887" loading="lazy">`:lockedCover();}
function progressSummary(){return `<section class="journey-progress" aria-label="Tu progreso en el Acto I"><div><strong>Tu recorrido · ${completed.length} de 12 estudios completados</strong><p>${reflections?.review?'El progreso de revisión se guarda por separado. ':''}${progressSaved?'Guardado en este navegador y dispositivo. Borrar los datos del sitio lo elimina; no se sincroniza con otros dispositivos.':'El almacenamiento del navegador no está disponible. Tu progreso durará solo durante esta visita.'}</p></div><progress max="12" value="${completed.length}" aria-label="Estudios completados">${completed.length} de 12</progress></section>`;}
function completionControl(s){if(!artAvailable(s))return `<section class="completion-control" aria-label="Finalización de la semana ${s.number}"><div><strong>${esc(openingLabel(s))}</strong><p>Disponible desde el lunes a las 06:00, hora de París.</p></div><button class="primary-button" disabled aria-disabled="true">Marcar semana ${s.number} como completada</button></section>`;const done=completed.includes(s.number),ready=storyAvailable(s.module);return `<section class="completion-control" aria-label="Finalización de la semana ${s.number}"><div><strong>${done?'✓ Estudio completado':'¿Terminaste este estudio?'}</strong><p>Después de leer, observar, interpretar, aplicar y orar, marca tu estudio aquí.</p></div><button class="${done?'secondary':'primary'}-button" data-complete="${s.number}" aria-pressed="${done}">${done?'Marcar semana '+s.number+' como pendiente':'Marcar semana '+s.number+' como completada'}</button>${ready?`<a class="text-link" href="#story">Volver a La historia hasta aquí ↗</a>`:''}</section>`;}
function sceneConnections(s){const item=journey.sessions[s.number-1],hints=weeklyStudy.sessions[s.number-1].hints;return `<section class="scene-connections" aria-labelledby="scene-${s.number}"><span class="eyebrow">UN POCO MÁS DE CONTEXTO</span><h4 id="scene-${s.number}">Dos pasajes para explorar</h4><div class="support-card-grid">${item.connections.map((p,i)=>`<article class="support-card"><button class="text-link" data-scene="${s.number}:${i}">Lee ${esc(p.reference)} ↗</button><p>${esc(hints[i])}</p></article>`).join('')}</div></section>`;}
function openScene(number,index){const s=journey.sessions[number-1],p=s?.connections[index];if(!p)return;openDialog('PASAJE RELACIONADO · RV1909',p.reference,`<p class="connection-hint">${esc(weeklyStudy.sessions[number-1].hints[index])}</p>${p.verses.map(v=>`<p class="scripture-quote"><sup>${v.verse}</sup>${esc(v.text)}</p>`).join('')}<a class="text-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Leer el capítulo completo ↗</a>`);}

async function ensureStories(){
 if(approvedStories)return approvedStories;
 if(reflections?.review){approvedStories=reflections;return approvedStories;}
 if(!storyPromise)storyPromise=fetchJSON($('meta[name="story-catalog"]').content,{cache:'no-store'}).then(data=>{approvedStories=data;return data}).catch(e=>{storyPromise=null;throw e});
 return storyPromise;
}
function tskView(){return `<h3 class="tool-heading">Concordancia bíblica TSK</h3><p class="info-note">Seis conexiones escogidas para cada pasaje de estudio. Sigue una palabra, una imagen compartida o una promesa anterior. Las notas breves orientan la lectura; no son citas de TSK.</p>${[session()].map(s=>`<section class="weekly-concordance"><header><span class="eyebrow">${weekLabel(s.date)}</span><h4>${esc(s.passage)}</h4><button class="text-link" data-read="${s.number}">Volver a la lectura de esta semana ↗</button></header><div class="concordance-grid">${weeklyStudy.sessions[s.number-1].concordance.map((c,i)=>`<article class="concordance-card"><span class="connection-origin">Desde ${esc(verseLabel(c.source)+(c.source==='Mic.5.5'?'a':''))}</span><button class="text-link" data-connection="${s.number}:${i}">${esc(refLabel(c.ref))} ↗</button><p>${esc(c.reason)}</p></article>`).join('')}</div></section>`).join('')}`;}
async function openConnection(number,index){const c=weeklyStudy.sessions[number-1]?.concordance[index];if(!c)return;await openReference(c.ref);if($('#detail').open&&$('#dialog-title')?.textContent===refLabel(c.ref)){const note=document.createElement('p');note.className='connection-hint';note.textContent=verseLabel(c.source)+(c.source==='Mic.5.5'?'a':'')+' → '+refLabel(c.ref)+'. '+c.reason;$('#dialog-title').after(note);}}

function toolsView(){const names={words:'Palabras repetidas',glossary:'Glosario',tsk:'Concordancia bíblica TSK'};return heading('05','Herramientas de estudio bíblico','Sigue una palabra, comprende una idea o compara pasajes relacionados.')+toolsWeekSelector()+`<div class="tool-tabs" role="tablist" aria-label="Herramientas de estudio bíblico">${Object.entries(names).map(([key,name])=>`<button role="tab" id="tool-tab-${key}" aria-controls="tool-panel" aria-selected="${state.tool===key}" tabindex="${state.tool===key?0:-1}" data-tool="${key}">${name}</button>`).join('')}</div><section id="tool-panel" role="tabpanel" aria-labelledby="tool-tab-${state.tool}">${({words,glossary:glossaryView,tsk:tskView}[state.tool])()}</section>`;}
function wireJourney(){
 document.querySelectorAll('[data-study-jump]').forEach(b=>b.onclick=()=>$('#study-start-'+b.dataset.studyJump)?.focus());
 document.querySelectorAll('[data-tools-tsk]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.toolsTsk);state.tool='tsk';go('tools');});
 document.querySelectorAll('[data-tool]').forEach(b=>{b.onclick=()=>{state.tool=b.dataset.tool;render();$('#tool-tab-'+state.tool).focus();};b.onkeydown=e=>{const keys=['words','glossary','tsk'],i=keys.indexOf(state.tool);let next;if(e.key==='ArrowRight')next=keys[(i+1)%3];if(e.key==='ArrowLeft')next=keys[(i+2)%3];if(e.key==='Home')next=keys[0];if(e.key==='End')next=keys[2];if(next){e.preventDefault();state.tool=next;render();$('#tool-tab-'+next).focus();}};});
 document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>openScene(...b.dataset.scene.split(':').map(Number)));
 document.querySelectorAll('[data-connection]').forEach(b=>b.onclick=()=>openConnection(...b.dataset.connection.split(':').map(Number)));
 document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=async()=>{
  const n=Number(b.dataset.complete);if(!artAvailable(curriculum.sessions[n-1])){render();return;}const wasDone=completed.includes(n);completed=toggleCompleted(completed,n,lessonMeta(curriculum.sessions[n-1])?.releaseAt);
  try{localStorage.setItem('lucas-hechos-es-'+progressKey(),JSON.stringify({version:1,completed}));progressSaved=true;}catch{progressSaved=false;}
  if(curriculum.modules.some(m=>storyAvailable(m.id))){try{await ensureStories()}catch{/* Completion stays saved. Opening the reading offers a retry. */}}
  render();document.querySelector(`[data-complete="${n}"]`)?.focus({preventScroll:true});
  showToast(!progressSaved?'Completado durante esta visita; el almacenamiento del navegador no está disponible.':wasDone?'Se quitó la marca de completado.':moduleCompleted(curriculum.sessions[n-1].module,curriculum.sessions,completed)?'Módulo completado. La historia hasta aquí está disponible.':'Estudio completado. Tu escena está disponible.');
 });
}
window.addEventListener('storage',async e=>{if(curriculum&&e.key==='lucas-hechos-es-'+progressKey()){completed=readProgress();if(curriculum.modules.some(m=>storyAvailable(m.id)))try{await ensureStories()}catch{}if(!$('#detail').open)render();}});

const sectionScenes={introduction:['intro','Introducción','Entra en la historia.'],reading:['read','Leer','Escucha el texto.'],studies:['studies','Comentarios pastorales','Enseñanza pastoral, una semana a la vez.'],story:['story','Historia','Descubre cómo se unen los hilos.'],tools:['tools','Herramientas','Mira las palabras más de cerca.'],resources:['resources','Recursos','Explora un poco más.']};
function sectionBanner(){const [id,title,copy]=sectionScenes[state.view];return `${['reading','studies','story','tools','resources'].includes(state.view)?`<div class="section-banner" aria-label="${title}">${id?`<img src="./assets/banner-${id}.webp?v=20261012-diversity" alt="" width="1536" height="512" decoding="async">`:""}<div><span class="eyebrow">DE BELÉN A LAS NACIONES · ACTO I</span><p class="banner-title">${title}</p><p>${copy}</p></div></div>`:''}<div class="location-trail" aria-label="Tu lugar en el estudio">Acto I <span aria-hidden="true">/</span> ${esc(navs.find(n=>n[0]===state.view)[1])}${['reading','studies','commentaries'].includes(state.view)?` <span aria-hidden="true">/</span> ${esc(weekLabel(session().date))}`:state.view==='tools'?` <span aria-hidden="true">/</span> ${esc({words:'Palabras repetidas',glossary:'Glosario',tsk:'Concordancia bíblica TSK'}[state.tool])}`:''}</div>`;}
function updateLocation(){const label=navs.find(n=>n[0]===state.view)[2];$('.breadcrumb').innerHTML=`<span class="crumb-series">Lucas–Hechos / Acto I</span><strong aria-current="page">${esc(label)}</strong>`;}
